-- Typed supplementary quote staging; the existing capture/promotion pipeline remains authoritative.
SET ANSI_NULLS ON;SET QUOTED_IDENTIFIER ON;
GO
CREATE TABLE ctl.analytic_quote_capture (
 execution_id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_ana_quote_capture PRIMARY KEY REFERENCES ctl.execution_attempt(execution_id),
 run_id UNIQUEIDENTIFIER NOT NULL REFERENCES ctl.analytic_lab_run(run_id),contract_fingerprint CHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 state VARCHAR(16) NOT NULL,started_at DATETIME2(7) NOT NULL,finished_at DATETIME2(7) NULL,
 physical_rows BIGINT NULL,roots BIGINT NULL,inserts BIGINT NULL,updates BIGINT NULL,noops BIGINT NULL,stale BIGINT NULL,blocked BIGINT NULL,
 CONSTRAINT UQ_ana_quote_capture_scope UNIQUE(execution_id,run_id),
 CONSTRAINT CK_ana_quote_capture CHECK(state IN('CAPTURING','PUBLISHED','DEGRADED')
 AND(state='CAPTURING' OR(roots>=0 AND inserts>=0 AND updates>=0 AND noops>=0 AND stale>=0 AND blocked>=0 AND physical_rows>=roots AND roots=inserts+updates+noops+stale+blocked AND finished_at IS NOT NULL)))
);
GO
