 comparison_bytes VARBINARY(MAX) NOT NULL,
 [requested_at_p] VARCHAR(6) NOT NULL,[requested_at_w] VARCHAR(8) NOT NULL,[requested_at_raw] NVARCHAR(4000) COLLATE Latin1_General_100_BIN2 NULL,[requested_at] BIGINT NULL,[requested_at_nano] INT NULL,
 [sequence_code_p] VARCHAR(6) NOT NULL,[sequence_code_w] VARCHAR(8) NOT NULL,[sequence_code_raw] NVARCHAR(4000) COLLATE Latin1_General_100_BIN2 NULL,[sequence_code] VARCHAR(40) COLLATE Latin1_General_100_BIN2 NULL,
