 OR (SELECT SUM(CONVERT(BIGINT,DATALENGTH(comparison_bytes))) FROM @rows)>262144
 OR NOT EXISTS(SELECT 1 FROM ctl.analytic_quote_capture WHERE execution_id=@execution_id AND run_id=@run_id AND state='CAPTURING')
 THROW 53693,N'ANA_QUOTE_ATTRIBUTE_SCOPE',1;
 IF EXISTS(SELECT 1 FROM @rows r WHERE r.input_ordinal NOT BETWEEN 1 AND 1000 OR DATALENGTH(r.comparison_bytes) NOT BETWEEN 1 AND 262144
 OR NOT EXISTS(SELECT 1 FROM stg.execution_record e JOIN stg.cotacao_record q ON q.stage_record_id=e.stage_record_id
 WHERE e.execution_id=@execution_id AND e.input_batch_number=@batch_number AND e.input_record_ordinal=r.input_ordinal
 AND q.source_key=r.source_key AND e.validation_disposition=N'VALID')) THROW 53694,N'ANA_QUOTE_ATTRIBUTE_SOURCE',1;
